         self._client_kwargs = {
             "timeout": timeout,
             "proxy": proxy,
             "limits": limits,
             "transport": transport,
             **http_kwargs,
         }

         try:
             self._client = self._build_client()
         except ImportError as exc:
             if "httpx[http2]" not in str(exc) and "httpx[socks]" not in str(exc):
                 raise exc

             if "httpx[socks]" in str(exc):
                 raise RuntimeError(
                     "To use Socks5 proxies, PTB must be installed via `pip install "
                     '"python-telegram-bot[socks]"`.'
                 ) from exc
             raise RuntimeError(
                 "To use HTTP/2, PTB must be installed via `pip install "
                 '"python-telegram-bot[http2]"`.'
             ) from exc

     @property
     def http_version(self) -> str:
         """
         :obj:`str`: Used HTTP version, see :paramref:`http_version`.

         .. versionadded:: 20.2
         """
         return self._http_version

     @property
     def read_timeout(self) -> Optional[float]:
         """See :attr:`BaseRequest.read_timeout`.

         Returns:
             :obj:`float` | :obj:`None`: The default read timeout in seconds as passed to
                 :paramref:`HTTPXRequest.read_timeout`.
         """
         return self._client.timeout.read

     def _build_client(self) -> httpx.AsyncClient:
         client_kwargs = self._client_kwargs.copy()
         client_parameters = signature(httpx.AsyncClient).parameters
         if "proxy" in client_kwargs and "proxy" not in client_parameters and "proxies" in client_parameters:
             client_kwargs["proxies"] = client_kwargs.pop("proxy")

